'use strict';

// MODULES //

var Symbol = require( '@stdlib/symbol/ctor' );
var ArrayBuffer = require( '@stdlib/array/buffer' );
var Float64Array = require( '@stdlib/array/float64' );
var isSafeInteger = require( '@stdlib/assert/is-safe-integer' ).isPrimitive;
var max = require( '@stdlib/math/base/special/max' );
var min = require( '@stdlib/math/base/special/min' );
var abs = require( '@stdlib/math/base/special/abs' );


// VARIABLES //

var MAX = 9007199254740991;
var prototype = Object.getPrototypeOf( Float64Array.prototype );
var tag = Object.getOwnPropertyDescriptor( prototype, Symbol.toStringTag ).get;
var getLength = Object.getOwnPropertyDescriptor( prototype, 'length' ).get;
var buffer = Object.getOwnPropertyDescriptor( prototype, 'buffer' ).get;
var byteOffset = Object.getOwnPropertyDescriptor( prototype, 'byteOffset' ).get;
var byteLength = Object.getOwnPropertyDescriptor( ArrayBuffer.prototype, 'byteLength' ).get;


// FUNCTIONS //

/**
* Validates primitive exact metadata.
* @private
* @param {number} value - metadata
* @throws {RangeError} invalid argument
* @returns {integer} validated value
*/
function integer( value ) {
	if ( !isSafeInteger( value ) ) {
		throw new RangeError( 'invalid argument. Metadata must be primitive safe integers.' );
	}
	return value;
}
/**
* Adds exact metadata without first evaluating an oversized expression.
* @private
* @param {integer} x - first value
* @param {integer} y - second value
* @throws {RangeError} invalid argument
* @returns {integer} exact sum
*/
function sum( x, y ) {
	if ( ((((y > 0) && (x > (MAX-y)))) || (((y < 0) && (x < (-MAX-y))))) ) {
		throw new RangeError( 'invalid argument. Inexact indexed sum.' );
	}
	return (x+y);
}
/**
* Checks a product and its actual primitive result.
* @private
* @param {NonNegativeInteger} n - factor
* @param {integer} s - signed stride
* @throws {RangeError} invalid argument
* @returns {integer} exact product
*/
function product( n, s ) {
	if ( ((n !== 0) && (abs(s) > (MAX/n))) ) {
		throw new RangeError( 'invalid argument. Inexact indexed product.' );
	}
	return integer( (n*s) );
}
/**
* Computes a positive greatest common divisor.
* @private
* @param {integer} x - first value
* @param {integer} y - second value
* @returns {PositiveInteger} divisor
*/
function gcd( x, y ) {
	var z;
	while ( (y !== 0) ) {
		z = (x%y);
		x = y;
		y = z;
	}
	return x;
}
/**
* Validates public triangle and signed32 dimensions before operands.
* @private
* @param {string|integer} uplo - selected triangle
* @param {NonNegativeInteger} N - matrix order
* @param {NonNegativeInteger} KD - bandwidth
* @throws {TypeError} invalid argument
* @throws {RangeError} invalid argument
* @returns {Object} derived geometry
*/
function scalars( uplo, N, KD ) {
	if ( ((uplo === 'upper') || (uplo === 121)) ) {
		uplo = 121;
	} else if ( ((uplo === 'lower') || (uplo === 122)) ) {
		uplo = 122;
	} else {
		throw new TypeError( 'invalid argument. Invalid triangle.' );
	}
	integer( N );
	if ( ((N < 0) || (N > 2147483647)) ) {
		throw new RangeError( 'invalid argument. N must be a nonnegative signed32 integer.' );
	}
	integer( KD );
	if ( ((KD < 0) || (KD > 2147483647)) ) {
		throw new RangeError( 'invalid argument. KD must be a nonnegative signed32 integer.' );
	}
	return {
		'uplo': uplo,
		'h': (KD+1),
		'empty': (N === 0)
	};
}


// MAIN //

/**
* Validates full injective current ordinary band storage before mutation.
* @private
* @param {PositiveInteger} h - band height
* @param {NonNegativeInteger} N - matrix order
* @param {Float64Array} AB - compact band storage
* @param {integer} r - band row stride
* @param {integer} c - band column stride
* @param {integer} o - band offset
* @throws {TypeError} invalid argument
* @throws {RangeError} invalid argument
* @returns {void}
*/
function validate( h, N, AB, r, c, o ) {
	var first;
	var data;
	var last;
	var dr;
	var dc;
	var lo;
	var hi;
	var g;
	if ( (tag.call(AB) !== 'Float64Array') ) {
		throw new TypeError( 'invalid argument. Must provide an intrinsic Float64Array.' );
	}
	data = buffer.call( AB );
	byteLength.call( data );

	// Ordinary backing brand rejects SAB, including clones.
	integer( r );
	integer( c );
	integer( o );
	if ( ((((h > 1) && (r === 0))) || (((N > 1) && (c === 0)))) ) {
		throw new RangeError( 'invalid argument. Active strides cannot broadcast.' );
	}
	if ( ((h > 1) && (N > 1)) ) {
		g = gcd( abs(r), abs(c) );
		if ( (((abs(c)/g) < h) && ((abs(r)/g) < N)) ) {
			throw new RangeError( 'invalid argument. The full band must be injective.' );
		}
	}
	dr = product( (h-1), r );
	dc = product( (N-1), c );
	lo = sum( sum(o, min(dr, 0)), min(dc, 0) );
	hi = sum( sum(o, max(dr, 0)), max(dc, 0) );
	if ( ((lo < 0) || (hi >= getLength.call(AB))) ) {
		throw new RangeError( 'invalid argument. Band exceeds the current intrinsic extent.' );
	}
	first = sum( byteOffset.call(AB), product(lo, 8) );
	last = sum( byteOffset.call(AB), product(sum(hi, 1), 8) );
	if ( ((first < 0) || (last > byteLength.call(data))) ) {
		throw new RangeError( 'invalid argument. Band exceeds the current backing extent.' );
	}
}


// EXPORTS //

validate.scalars = scalars;
validate.integer = integer;
validate.sum = sum;
validate.product = product;
validate.gcd = gcd;
module.exports = validate;
